class Rational {int n,d;static int gcd(int a,int b){return b==0?a:gcd(b,a%b);}Rational(int n,int d){if(d==0)throw new IllegalArgumentException();int g=gcd(Math.abs(n),Math.abs(d));this.n=n/g*(d<0?-1:1);this.d=Math.abs(d)/g;}int getNumerator(){return n;}int getDenominator(){return d;}Rational add(Rational r){return new Rational(n*r.d+r.n*d,d*r.d);}Rational subtract(Rational r){return new Rational(n*r.d-r.n*d,d*r.d);}Rational multiply(Rational r){return new Rational(n*r.n,d*r.d);}Rational divide(Rational r){return new Rational(n*r.d,d*r.n);}Rational abs(){return new Rational(Math.abs(n),d);}Rational pow(int p){return p<0?new Rational((int)Math.pow(d,-p),(int)Math.pow(n,-p)):new Rational((int)Math.pow(n,p),(int)Math.pow(d,p));}double exp(double x){return Math.pow(x,(double)n/d);}}